def explained_variance(returns, values):
    # your code
    pass

practice.solution:
def explained_variance(returns, values):
    n = len(returns)
    mu = sum(returns) / n
    var_r = sum((r - mu) ** 2 for r in returns) / n
    if var_r == 0:
        return 0
    diff = [r - v for r, v in zip(returns, values)]
    md = sum(diff) / n
    var_d = sum((d - md) ** 2 for d in diff) / n
    return round(1 - var_d / var_r, 6)

